widget.solution:
import math

def norm_cdf(z):
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))

def bs_call(S, K, T, sigma):
    """Black-Scholes call price with zero interest rates."""
    d1 = (math.log(S / K) + 0.5 * sigma * sigma * T) / (sigma * math.sqrt(T))
    d2 = d1 - sigma * math.sqrt(T)
    return S * norm_cdf(d1) - K * norm_cdf(d2)

def implied_vol(price, S, K, T):
    """The sigma in [0.0001, 5] with bs_call(S, K, T, sigma) = price,
    by bisection until the interval is narrower than 1e-10."""
    lo, hi = 0.0001, 5.0
    while hi - lo > 1e-10:
        mid = (lo + hi) / 2
        if bs_call(S, K, T, mid) < price:   # price rises with sigma
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2
